use verus::prelude::*;

verus! {

    /// The result of solving a single test case.
    #[verifier(publish)]
    enum SolveResult {
        /// No valid solution exists.
        Impossible,

        /// A valid solution exists, carrying a total `cost` and a list of `edges`.
        Possible {
            cost: i64,
            edges: Vec<(i8, i8)>,
        },
    }

    impl SolveResult {
        /// A trivial constructor for the `Impossible` variant.
        #[verifier(inline)]
        pub spec fn impossible() -> SolveResult {
            SolveResult::Impossible
        }
    }

    /// solve:
    ///   * t: the number of test cases (must be ≥ 0)
    ///   * cases: vector of (n, m, arr) triples, where
    ///       - n ≥ 0
    ///       - arr.len() == n
    ///   Returns a vector of length t, each entry marked `Impossible`.
    fn solve(t: i8, cases: Vec<(i8, i8, Vec<i8>)>) -> Vec<SolveResult>
        requires
            t >= 0,
            // The number of provided cases matches t
            (cases.len() as i8) == t,
            // Each case has the correct array length
            forall(|i: usize| i < cases.len() ==>
                let (n, _m, ref arr) = cases[i];
                n >= 0 && arr.len() == (n as usize)
            ),
        ensures |results: &Vec<SolveResult>| results.len() as i8 == t,
    {
        let mut results: Vec<SolveResult> = Vec::new();
        let mut idx: usize = 0;

        // Build a results vector of the correct length,
        // marking every entry `Impossible`.
        while idx < cases.len() {
            invariant idx <= cases.len();
            invariant results.len() == idx;

            results.push(SolveResult::Impossible);

            idx += 1;
        }

        results
    }
}